namespace Shop;

public enum CustomerType { Regular, Loyal, Employee }

public record OrderLine(string Sku, decimal UnitPrice, int Quantity);

public record Order(CustomerType Customer, IReadOnlyList<OrderLine> Lines);

public static class PriceCalculator
{
    public static decimal Total(Order order)
    {
        var subtotal = order.Lines.Sum(l => l.UnitPrice * l.Quantity);
        return subtotal - subtotal * DiscountRate(order.Customer);
    }

    // Adding a customer type: add the enum value and its rate here.
    public static decimal DiscountRate(CustomerType customer) => customer switch
    {
        CustomerType.Regular => 0m,
        CustomerType.Loyal => 0.05m,
        CustomerType.Employee => 0.20m,
        _ => throw new ArgumentOutOfRangeException(nameof(customer), customer, "No discount rate defined.")
    };
}

